// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

class ReifiedTripleRefBindingNamesTest {

	@Test
	void standaloneDoesNotAssureReifierItDoesNotBind() {
		ReifiedTripleRef ref = reifiedTripleRef();

		assertThat(ref.getBindingNames())
				.containsExactlyInAnyOrder("subject", "predicate", "object", "tripleTerm");
		assertThat(ref.getAssuredBindingNames())
				.containsExactlyInAnyOrder("subject", "predicate", "object", "tripleTerm");
	}

	@Test
	void reifierRemainsTraversalMetadata() {
		ReifiedTripleRef ref = reifiedTripleRef();

		assertThat(ref.getVarList())
				.extracting(Var::getName)
				.containsExactly("subject", "predicate", "object", "tripleTerm", "reifier");
	}

	private static ReifiedTripleRef reifiedTripleRef() {
		return new ReifiedTripleRef(
				new Var("subject"),
				new Var("predicate"),
				new Var("object"),
				new Var("tripleTerm"),
				new Var("reifier"));
	}
}
